import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as n,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"用 PGP 保护代码完整性（四）：将主密钥移到离线存储中 | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保护代码完整性（四）：将主密钥移到离线存储中 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保护代码完整性（四）：将主密钥移到离线存储中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保护代码完整性（四）：将主密钥移到离线存储中 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage","title":"用 PGP 保护代码完整性（四）：将主密钥移到离线存储中","tag":"201901","desc":""},"relativePath":"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage.md","filePath":"[post].md"}'),g={name:"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage.md"};function u(h,s,k,c,b,f){const e=p("Link");return r(),o("div",null,[s[19]||(s[19]=i("h1",{id:"用-pgp-保护代码完整性-四-将主密钥移到离线存储中",tabindex:"-1"},[a("用 PGP 保护代码完整性（四）：将主密钥移到离线存储中 "),i("a",{class:"header-anchor",href:"#用-pgp-保护代码完整性-四-将主密钥移到离线存储中","aria-label":"Permalink to “用 PGP 保护代码完整性（四）：将主密钥移到离线存储中”"},"​")],-1)),s[20]||(s[20]=i("blockquote",null,[i("p",null,"如果开发者的 PGP 密钥被偷了，危害非常大。了解一下如何更安全。")],-1)),s[21]||(s[21]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/industry-1920.jpg?itok=gI3QraS8",alt:""})],-1)),s[22]||(s[22]=i("p",null,"在本系列教程中，我们为使用 PGP 提供了一个实用指南。你可以从下面的链接中查看前面的文章：",-1)),i("ul",null,[i("li",null,[n(e,{href:"https://linux.cn/article-9524-1.html"},{default:t(()=>[...s[0]||(s[0]=[a("第一部分：基本概念和工具",-1)])]),_:1})]),i("li",null,[n(e,{href:"https://linux.cn/article-9529-1.html"},{default:t(()=>[...s[1]||(s[1]=[a("第二部分：生成你的主密钥",-1)])]),_:1})]),i("li",null,[n(e,{href:"https://linux.cn/article-9607-1.html"},{default:t(()=>[...s[2]||(s[2]=[a("第三部分：生成 PGP 子密钥",-1)])]),_:1})])]),s[23]||(s[23]=d(`<p>这是本系列教程的第四部分，我们继续本教程，我们将谈一谈如何及为什么要将主密钥从你的家目录移到离线存储中。现在开始我们的教程。</p><h4 id="清单" tabindex="-1">清单 <a class="header-anchor" href="#清单" aria-label="Permalink to “清单”">​</a></h4><ul><li>准备一个加密的可移除的存储（必要）</li><li>备份你的 GnuPG 目录（必要）</li><li>从你的家目录中删除主密钥（推荐）</li><li>从你的家目录中删除吊销证书（推荐）</li></ul><h4 id="考虑事项" tabindex="-1">考虑事项 <a class="header-anchor" href="#考虑事项" aria-label="Permalink to “考虑事项”">​</a></h4><p>为什么要从你的家目录中删除你的主 [C] 密钥 ？这样做的主要原因是防止你的主密钥失窃或意外泄露。对于心怀不轨的人来说，私钥对他们具有很大的诱惑力 —— 我们知道有几个恶意软件成功地实现了扫描用户的家目录并将发现的私钥内容上传。</p><p>对于开发者来说，私钥失窃是非常危险的事情 —— 在自由软件的世界中，这无疑是身份证明失窃。从你的家目录中删除私钥将帮你防范这类事件的发生。</p><h4 id="备份你的-gnupg-目录" tabindex="-1">备份你的 GnuPG 目录 <a class="header-anchor" href="#备份你的-gnupg-目录" aria-label="Permalink to “备份你的 GnuPG 目录”">​</a></h4><p><strong>!!!绝对不要跳过这一步!!!</strong></p><p>备份你的 PGP 密钥将让你在需要的时候很容易地恢复它们，这很重要！（这与我们做的使用 paperkey 的灾难级备份是不一样的）。</p><h4 id="准备可移除的加密存储" tabindex="-1">准备可移除的加密存储 <a class="header-anchor" href="#准备可移除的加密存储" aria-label="Permalink to “准备可移除的加密存储”">​</a></h4><p>我们从取得一个（最好是两个）小型的 USB “拇指“ 驱动器（可加密 U 盘）开始，我们将用它来做备份。你首先需要去加密它们：</p><p>加密密码可以使用与主密钥相同的密码。</p><h4 id="备份你的-gnupg-目录-1" tabindex="-1">备份你的 GnuPG 目录 <a class="header-anchor" href="#备份你的-gnupg-目录-1" aria-label="Permalink to “备份你的 GnuPG 目录”">​</a></h4><p>加密过程结束之后，重新插入 USB 驱动器并确保它能够正常挂载。你可以通过运行 <code>mount</code> 命令去找到设备挂载点的完全路径。（在 Linux 下，外置介质一般挂载在 <code>/media/disk</code> 下，Mac 一般在它的 <code>/Volumes</code> 下）</p><p>你知道了挂载点的全路径后，将你的整个 GnuPG 的目录复制进去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp -rp ~/.gnupg [/media/disk/name]/gnupg-backup</span></span></code></pre></div><p>（注意：如果出现任何套接字不支持的错误，没有关系，直接忽略它们。）</p><p>现在，用如下的命令去测试一下，确保它们能够正常地工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --homedir=[/media/disk/name]/gnupg-backup --list-key [fpr]</span></span></code></pre></div><p>如果没有出现任何错误，说明一切正常。弹出这个 USB 驱动器并给它粘上一个明确的标签，以便于你下次需要它时能够很快找到它。接着，将它放到一个安全的 —— 但不要太远 —— 的地方，因为从现在起，你需要偶尔使用它来做一些像编辑身份信息、添加或吊销子证书、或签署其它人的密钥这样的事情。</p><h4 id="删除主密钥" tabindex="-1">删除主密钥 <a class="header-anchor" href="#删除主密钥" aria-label="Permalink to “删除主密钥”">​</a></h4><p>我们家目录中的文件并没有像我们所想像的那样受到保护。它们可能会通过许多不同的方式被泄露或失窃：</p><ul><li>通过快速复制来配置一个新工作站时的偶尔事故</li><li>通过系统管理员的疏忽或恶意操作</li><li>通过安全性欠佳的备份</li><li>通过桌面应用中的恶意软件（浏览器、pdf 查看器等等）</li><li>通过跨境胁迫</li></ul><p>使用一个很好的密码来保护你的密钥是降低上述风险的一个很好方法，但是密码能够通过键盘记录器、背后窥视、或其它方式被发现。基于以上原因，我们建议去配置一个从你的家目录上可移除的主密钥，将它保存在一个离线存储中。</p><h5 id="删除你的主密钥" tabindex="-1">删除你的主密钥 <a class="header-anchor" href="#删除你的主密钥" aria-label="Permalink to “删除你的主密钥”">​</a></h5><p><strong>请查看前面的节，确保你有完整的你的 GnuPG 目录的一个备份。如果你没有一个可用的备份，下面所做的操作将会使你的主密钥失效！！！</strong></p><p>首先，识别你的主密钥的 keygrip：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --with-keygrip --list-key [fpr]</span></span></code></pre></div><p>它的输出应该像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pub   rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span>     111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>     Keygrip = AAAA999988887777666655554444333322221111</span></span>
<span class="line"><span>uid           [ultimate] Alice Engineer &lt;alice@example.org&gt;</span></span>
<span class="line"><span>uid           [ultimate] Alice Engineer &lt;allie@example.net&gt;</span></span>
<span class="line"><span>sub   rsa2048 2017-12-06 [E]</span></span>
<span class="line"><span>     Keygrip = BBBB999988887777666655554444333322221111</span></span>
<span class="line"><span>sub   rsa2048 2017-12-06 [S]</span></span>
<span class="line"><span>     Keygrip = CCCC999988887777666655554444333322221111</span></span></code></pre></div><p>找到 <code>pub</code> 行下方的 <code>Keygrip</code> 条目（就在主密钥指纹的下方）。它与你的家目录下 <code>.gnupg</code> 目录下的一个文件是一致的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>AAAA999988887777666655554444333322221111.key</span></span>
<span class="line"><span>BBBB999988887777666655554444333322221111.key</span></span>
<span class="line"><span>CCCC999988887777666655554444333322221111.key</span></span></code></pre></div><p>现在你做的全部操作就是简单地删除与主密钥 keygrip 一致的 <code>.key</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>$ rm AAAA999988887777666655554444333322221111.key</span></span></code></pre></div><p>现在，如果运行 <code>--list-secret-keys</code> 命令将出现问题，它将显示主密钥丢失（<code>#</code> 表示不可用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --list-secret-keys</span></span>
<span class="line"><span>sec# rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span> 111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>uid [ultimate] Alice Engineer &lt;alice@example.org&gt;</span></span>
<span class="line"><span>uid [ultimate] Alice Engineer &lt;allie@example.net&gt;</span></span>
<span class="line"><span>ssb rsa2048 2017-12-06 [E]</span></span>
<span class="line"><span>ssb rsa2048 2017-12-06 [S]</span></span></code></pre></div><h4 id="删除吊销证书" tabindex="-1">删除吊销证书 <a class="header-anchor" href="#删除吊销证书" aria-label="Permalink to “删除吊销证书”">​</a></h4><p>你应该去删除的另一个文件是吊销证书（<strong>删除之前，确保你的备份中有它</strong>），它是使用你的主密钥自动创建的。吊销证书允许一些人去永久标记你的证书为吊销状态，这意味着它无论在任何用途中将不再被使用或信任。一般是使用它来吊销由于某些原因不再受控的一个密钥 —— 比如，你丢失了密钥密码。</p><p>与使用主密钥一样，如果一个吊销证书泄露到恶意者手中，他们能够使用它去破坏你的开发者数字身份，因此，最好是从你的家目录中删除它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~/.gnupg/openpgp-revocs.d</span></span>
<span class="line"><span>rm [fpr].rev</span></span></code></pre></div><p>在下一篇文章中，你将学习如何保护你的子密钥。敬请期待。</p>`,41)),i("p",null,[s[4]||(s[4]=a("从来自 Linux 基金会和 edX 的免费课程 ",-1)),n(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[3]||(s[3]=[a("“Linux 入门”",-1)])]),_:1}),s[5]||(s[5]=a(" 中学习更多 Linux 知识。",-1))]),s[24]||(s[24]=i("hr",null,null,-1)),i("p",null,[s[7]||(s[7]=a("via: ",-1)),n(e,{href:"https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-4-moving-your-master-key-offline-storage"},{default:t(()=>[...s[6]||(s[6]=[a("https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-4-moving-your-master-key-offline-storage",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),n(e,{href:"https://www.linux.com/users/mricon"},{default:t(()=>[...s[8]||(s[8]=[a("Konstantin Ryabitsev",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),n(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[9]||(s[9]=[a("qhwdw",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const C=l(g,[["render",u]]);export{P as __pageData,C as default};
